<?php require '../config.php';if(!empty($_SESSION['admin'])){header('Location:index.php');exit;}$err='';if($_SERVER['REQUEST_METHOD']==='POST'){verify();$s=db()->prepare("SELECT * FROM admins WHERE email=?");$s->execute([trim($_POST['email']??'')]);$a=$s->fetch();if($a&&password_verify($_POST['password']??'',$a['password_hash'])){$_SESSION['admin']=$a['id'];header('Location:index.php');exit;}$err='Invalid credentials.';}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>DeskFlow Admin</title><link rel="stylesheet" href="../assets/style.css"></head><body class="stafflogin"><div class="staffcard"><a class="logo" href="../index.php"><span>desk</span>flow</a><h1>Staff workspace</h1><p>Manage requests and knowledge base content.</p><?php if($err):?><div class="err"><?=e($err)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Email<input type="email" name="email" value="admin@deskflow.local" required></label><label>Password<input type="password" name="password" value="admin" required></label><button>Sign in</button></form><small>Default: admin@deskflow.local / admin</small></div></body></html>